agent_base_units.command:
cd /app && python - <<'EOF'
p='packages/core/src/world/deferred.ts'
s=open(p).read()
old_pair="""        const pairState = relationMap.get(pairCtx.target)!;
        if (pairState.hasParams) return pairState.params;
        if (state.isSpawn) return getTraitDefaults(relation[$internal].trait) ?? undefined;
        return getRelationData(world, entity, relation, pairCtx.target);
"""
new_pair="""        const pairState = relationMap.get(pairCtx.target)!;
        if (pairState.hasParams) return pairState.params;
        const liveData = getRelationData(world, entity, relation, pairCtx.target);
        if (liveData !== undefined) return liveData;
        return getTraitDefaults(relation[$internal].trait) ?? undefined;
"""
s=s.replace(old_pair,new_pair)
old_trait="""    const traitState = state.traits.get(target);
    if (!traitState || !traitState.present) return undefined;
    if (traitState.hasParams) return traitState.params;
    if (state.isSpawn) return getTraitDefaults(target) ?? undefined;
    return getTrait(world, entity, target);
"""
new_trait="""    const traitState = state.traits.get(target);
    if (!traitState || !traitState.present) return undefined;
    if (traitState.hasParams) return traitState.params;
    const liveValue = getTrait(world, entity, target);
    if (liveValue !== undefined) return liveValue;
    return getTraitDefaults(target) ?? undefined;
"""
s=s.replace(old_trait,new_trait)
open(p,'w').write(s)
EOF
cd packages/core && ../../node_modules/.bin/tsc --noEmit -p tsconfig.json 2>&1 | head -10
cd /app && cat > /tmp/tt4.ts <<'EOF'
import { createWorld, relation, trait, universe } from '/app/packages/core/src/index';
universe.reset();
const A = trait({ value: 0 });
const Likes = relation({ store: { amount: 0 } });
const world = createWorld();
const subj = world.spawn();
const target = world.deferred.spawn();
world.deferred.add(subj, Likes(target, { amount: 7 }));
console.log('pair get before', subj.get(Likes(target)));
const subj2 = world.spawn();
const target2 = world.spawn();
world.deferred.add(subj2, Likes(target2));
console.log('pair default before', subj2.get(Likes(target2)));
const e = world.spawn();
world.deferred.add(e, A());
console.log('trait default before', e.get(A));
EOF
pnpm exec tsx /tmp/tt4.ts 2>&1 | tail -10

